CREATE TABLE "C##XCHEL_MEDICAL_RECORDS"."CHRONIC_DISEASES"(
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY
    (START WITH 1 MINVALUE 1 NOMAXVALUE INCREMENT BY 1 NOCYCLE),
	"UUID" VARCHAR2(36) NOT NULL UNIQUE,
	"NAME" VARCHAR2(50) NOT NULL,
	"CREATED_DATE" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"UPDATED_DATE" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"ACTIVE" CHAR(1) NOT NULL CHECK (active IN ('Y', 'N')),
  PRIMARY KEY("ID")
);

CREATE TABLE "C##XCHEL_MEDICAL_RECORDS"."DISEASES_BY_CLINICAL_HISTORY"(
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY
    (START WITH 1 MINVALUE 1 NOMAXVALUE INCREMENT BY 1 NOCYCLE),
	"UUID" VARCHAR2(36) NOT NULL UNIQUE,
	"CLINICAL_HISTORY_ID" INTEGER NOT NULL,
	"CHRONIC_DISEASE_ID" INTEGER NOT NULL,
	"CREATED_DATE" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"UPDATED_DATE" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"ACTIVE" CHAR(1) CHECK (active IN ('Y', 'N')) NOT NULL, 
	PRIMARY KEY ("ID")
);

CREATE TABLE "C##XCHEL_MEDICAL_RECORDS"."MEDICAL_RECORDS"(
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY
    (START WITH 1 MINVALUE 1 NOMAXVALUE INCREMENT BY 1 NOCYCLE),
	"UUID" VARCHAR2(36) NOT NULL UNIQUE,
	"ALLERGIES" VARCHAR2(200) NOT NULL,
	"WEIGHT" FLOAT,
	"HEIGHT" FLOAT NOT NULL,
	"BLOOD_PRESSURE" VARCHAR2(7),
	"HEART_RATE_BPM" NUMBER(3,0),
	"LAST_MEDICAL_PRESCRIPTION_UUID" VARCHAR2(36) NOT NULL UNIQUE,
	"CREATED_DATE" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"UPDATED_DATE" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"PATIENT_UUID" VARCHAR2(36) NOT NULL UNIQUE,
	"ACTIVE" CHAR(1) CHECK ("ACTIVE" IN ('Y', 'N')) NOT NULL,
	PRIMARY KEY ("ID")
);

ALTER TABLE "C##XCHEL_MEDICAL_RECORDS"."DISEASES_BY_CLINICAL_HISTORY"
  ADD CONSTRAINT "DISEASES_BY_CLINICAL_HISTORY_MEDICAL_RECORDS_FK"
    FOREIGN KEY ("CLINICAL_HISTORY_ID")
		REFERENCES "C##XCHEL_MEDICAL_RECORDS"."MEDICAL_RECORDS" ("ID")
			ON DELETE CASCADE;

ALTER TABLE "C##XCHEL_MEDICAL_RECORDS"."DISEASES_BY_CLINICAL_HISTORY"
  ADD CONSTRAINT "DISEASES_BY_CLINICAL_HISTORY_CHRONIC_DISEASES_FK"
    FOREIGN KEY ("CHRONIC_DISEASE_ID")
		REFERENCES "C##XCHEL_MEDICAL_RECORDS"."CHRONIC_DISEASES" ("ID")
			ON DELETE CASCADE;
